{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

function changes(base, side, who) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const out = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) out.push({ who, bs, be: i, ss, se: j })
  }
  while (i < n || j < m) {
    if (i < n && j < m && base[i] === side[j]) {
      flush()
      i++; j++; bs = i; ss = j
    } else if (i < n && (j >= m || L[i + 1][j] >= L[i][j + 1])) i++
    else j++
  }
  flush()
  return out
}

const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

const mode = process.argv.length === 3 ? process.argv[2] : null
if (!['merge', 'merge2', 'regions'].includes(mode)) fail('error: usage: cli.js merge|merge2|regions')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()
const docs = [[]]
for (const l of lines) l === '%%%' ? docs.push([]) : docs[docs.length - 1].push(l)
if (docs.length !== 3) fail('error: expected three parts separated by %%%')
const [mine, base, theirs] = docs

const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
all.sort((a, b) => a.bs - b.bs || a.who - b.who)

const out = []
let conflict = false
const sides = [mine, theirs]
let pos = 0
const stable = (to) => {
  if (to > pos) {
    const seg = base.slice(pos, to)
    if (mode === 'regions') out.push(`stable ${seg.length}`)
    else out.push(...seg)
  }
}
let k = 0
while (k < all.length) {
  const rs = all[k].bs
  let re = all[k].be
  const group = [all[k++]]
  while (k < all.length && all[k].bs <= re) {
    re = Math.max(re, all[k].be)
    group.push(all[k++])
  }
  stable(rs)
  pos = re
  const rep = [0, 1].map(w => {
    const g = group.filter(c => c.who === w)
    if (!g.length) return base.slice(rs, re)
    const minBS = Math.min(...g.map(c => c.bs)), maxBE = Math.max(...g.map(c => c.be))
    const s = Math.min(...g.map(c => c.ss)) - (minBS - rs)
    const e = Math.max(...g.map(c => c.se)) + (re - maxBE)
    return sides[w].slice(s, e)
  })
  const [M, T] = rep
  const B = base.slice(rs, re)
  let res, label
  if (group.length === 1) {
    label = group[0].who ? 'theirs' : 'mine'
    res = rep[group[0].who]
  } else if (eq(M, T)) { res = M; label = 'both' }
  else if (eq(M, B)) { res = T; label = 'theirs' }
  else if (eq(T, B)) { res = M; label = 'mine' }
  else label = 'conflict'
  if (label === 'conflict') {
    conflict = true
    if (mode === 'regions') out.push(`conflict mine=${M.length} base=${B.length} theirs=${T.length}`)
    else {
      out.push('<<<<<<< mine', ...M)
      if (mode === 'merge') out.push('||||||| base', ...B)
      out.push('=======', ...T, '>>>>>>> theirs')
    }
  } else if (mode === 'regions') out.push(`${label} ${res.length}`)
  else out.push(...res)
}
stable(base.length)
process.stdout.write(out.map(l => l + '\n').join(''))
process.exitCode = conflict ? 1 : 0
